    uk: 'Кількість осіб впливає на ціни й реєстраційну картку, а не на місткість.',
    zh: '入住人数影响价格和登记表，不影响容量。',
    ko: '투숙 인원은 요금과 숙박 신고서에 영향을 주며, 객실 수에는 영향을 주지 않습니다.',
