    sr: 'Broj osoba utiče na cene i prijavni list, ne na kapacitet.',
    mk: 'Бројот на лица влијае на цените и на пријавниот лист, не на капацитетот.',
    sq: 'Numri i personave ndikon te çmimet dhe te formulari i regjistrimit, jo te kapaciteti.',
    el: 'Ο αριθμός ατόμων επηρεάζει τιμές και έντυπο δήλωσης διαμονής, όχι τη χωρητικότητα.',
    lt: 'Asmenų skaičius veikia kainas ir registracijos kortelę, ne pajėgumą.',
