  'master.roomNameHint': {
    de: 'Optional, z. B. „Dünenblick“. Steht im Kalender neben der Nummer.',
    en: 'Optional, e.g. “Dune View”. Shown next to the number in the calendar.',
    tr: 'İsteğe bağlı, ör. „Kumul Manzarası“. Takvimde numaranın yanında görünür.',
    nl: 'Optioneel, bijv. “Duinzicht”. Staat in de kalender naast het nummer.',
    da: 'Valgfrit, f.eks. „Klitudsigt“. Vises i kalenderen ved siden af nummeret.',
    sv: 'Valfritt, t.ex. ”Dynutsikt”. Visas bredvid numret i kalendern.',
    nb: 'Valgfritt, f.eks. «Dyneutsikt». Vises i kalenderen ved siden av nummeret.',
    pl: 'Opcjonalnie, np. „Widok na wydmy”. Wyświetlane w kalendarzu obok numeru.',
    cs: 'Nepovinné, např. „Výhled na duny“. Zobrazí se v kalendáři vedle čísla.',
    fr: 'Facultatif, p. ex. « Vue sur les dunes ». Affiché à côté du numéro dans le planning.',
    it: 'Facoltativo, ad es. «Vista dune». Compare nel calendario accanto al numero.',
    es: 'Opcional, p. ej. «Vista a las dunas». Aparece en el calendario junto al número.',
    ru: 'Необязательно, например «Вид на дюны». Показывается в календаре рядом с номером.',
    uk: 'Необов’язково, напр. «Вид на дюни». Показується в календарі поруч із номером.',
    zh: '可选，例如“Dünenblick”。在日历中显示在房号旁边。',
    ko: '선택 사항, 예: „듄 뷰“. 캘린더에서 번호 옆에 표시됩니다.',
    ar: 'اختياري، مثل «إطلالة الكثبان». يظهر في التقويم بجانب الرقم.',
    pt: 'Opcional, p. ex. «Vista Dunas». Aparece no calendário ao lado do número.',
    fi: 'Valinnainen, esim. ”Dyyninäkymä”. Näkyy kalenterissa numeron vieressä.',
    is: 'Valfrjálst, t.d. „Sandhólasýn“. Birtist við hlið númersins í dagatalinu.',
    sk: 'Nepovinné, napr. „Výhľad na duny“. Zobrazuje sa v kalendári vedľa čísla.',
    sl: 'Neobvezno, npr. „Pogled na sipine“. V koledarju je prikazano poleg številke.',
    hu: 'Nem kötelező, pl. „Dűnére néző”. A naptárban a szám mellett jelenik meg.',
    ro: 'Opțional, de ex. „Vedere spre dune”. Apare în calendar lângă număr.',
    bg: 'По избор, напр. „Изглед към дюните“. Показва се до номера в календара.',
    hr: 'Neobavezno, npr. „Pogled na dine“. Prikazuje se u kalendaru uz broj.',
    sr: 'Opciono, npr. „Pogled na dine“. Prikazuje se u kalendaru pored broja.',
    mk: 'Опционално, на пр. „Поглед на дините“. Стои во календарот покрај бројот.',
    sq: 'Opsionale, p.sh. „Pamje nga dunat“. Shfaqet në kalendar pranë numrit.',
    el: 'Προαιρετικά, π.χ. «Θέα στους αμμόλοφους». Εμφανίζεται στο ημερολόγιο δίπλα στον αριθμό.',
    lt: 'Neprivaloma, pvz., „Vaizdas į kopas“. Rodoma kalendoriuje šalia numerio.',
    lv: 'Neobligāti, piem., “Skats uz kāpām”. Kalendārā redzams blakus numuram.',
    et: 'Valikuline, nt „Luitevaade“. Kuvatakse kalendris numbri kõrval.' },
