  'master.salesCodeHint': {
    de: 'Nur nötig, wenn ein Kanal dieses Zimmer unter einer eigenen Kategorie verkauft, etwa FZ und APT in derselben Zimmergruppe.',
    en: 'Only needed if a channel sells this room under its own category, such as FZ and APT in the same room category.',
    tr: 'Yalnızca bir kanal bu odayı kendi kategorisiyle satıyorsa gerekir, örneğin aynı oda tipinde FZ ve APT.',
    nl: 'Alleen nodig als een kanaal deze kamer onder een eigen categorie verkoopt, zoals FZ en APT in hetzelfde kamertype.',
    da: 'Kun nødvendig, hvis en kanal sælger dette værelse under sin egen kategori, f.eks. FZ og APT i samme værelsestype.',
    sv: 'Behövs bara om en kanal säljer detta rum under en egen kategori, t.ex. FZ och APT i samma rumstyp.',
    nb: 'Bare nødvendig hvis en kanal selger dette rommet under en egen kategori, f.eks. FZ og APT i samme romtype.',
    pl: 'Potrzebny tylko wtedy, gdy kanał sprzedaje ten pokój w ramach własnej kategorii, np. FZ i APT w tej samej grupie pokoi.',
    cs: 'Potřeba jen tehdy, když kanál prodává tento pokoj pod vlastní kategorií, např. FZ a APT ve stejné skupině pokojů.',
    fr: 'Nécessaire seulement si un canal vend cette chambre sous sa propre catégorie, comme FZ et APT dans la même catégorie de chambre.',
    it: 'Necessario solo se un canale vende questa camera con una propria categoria, ad esempio FZ e APT nella stessa tipologia.',
    es: 'Solo es necesario si un canal vende esta habitación bajo una categoría propia, p. ej. FZ y APT en el mismo tipo de habitación.',
    ru: 'Нужен, только если канал продаёт этот номер под собственной категорией, например FZ и APT в одной категории номеров.',
    uk: 'Потрібен лише тоді, коли канал продає цей номер під власною категорією, напр. FZ і APT в одному типі номерів.',
    zh: '仅当某个渠道以自己的类别销售此客房时才需要，例如同一房型中的 FZ 和 APT。',
    ko: '채널이 이 객실을 별도의 카테고리로 판매하는 경우에만 필요합니다(예: 같은 객실 유형 내의 FZ와 APT).',
    ar: 'لا يلزم إلا إذا كانت قناة ما تبيع هذه الغرفة تحت فئة خاصة بها، مثل FZ وAPT في فئة الغرف نفسها.',
    pt: 'Só é necessário se um canal vender este quarto numa categoria própria, como FZ e APT no mesmo grupo de quartos.',
    fi: 'Tarvitaan vain, jos jokin kanava myy tätä huonetta omana luokkanaan, esim. FZ ja APT samassa huonetyypissä.',
    is: 'Aðeins nauðsynlegt ef rás selur þetta herbergi undir eigin flokki, t.d. FZ og APT í sama herbergjaflokki.',
    sk: 'Potrebné len vtedy, ak kanál predáva túto izbu pod vlastnou kategóriou, napríklad FZ a APT v tej istej skupine izieb.',
    sl: 'Potrebno le, če kanal to sobo prodaja pod lastno kategorijo, npr. FZ in APT v isti skupini sob.',
    hu: 'Csak akkor kell, ha egy csatorna ezt a szobát saját kategóriában értékesíti, például FZ és APT ugyanabban a szobatípusban.',
    ro: 'Necesar doar dacă un canal vinde această cameră sub o categorie proprie, de ex. FZ și APT în același tip de cameră.',
    bg: 'Нужен е само ако канал продава тази стая под собствена категория, напр. FZ и APT в един и същ тип стая.',
    hr: 'Potrebno samo ako neki kanal prodaje ovu sobu pod vlastitom kategorijom, npr. FZ i APT u istom tipu sobe.',
    sr: 'Potrebno samo ako neki kanal prodaje ovu sobu pod sopstvenom kategorijom, npr. FZ i APT u istom tipu sobe.',
    mk: 'Потребно само ако некој канал ја продава оваа соба под сопствена категорија, на пр. FZ и APT во истата група соби.',
    sq: 'I nevojshëm vetëm nëse një kanal e shet këtë dhomë nën një kategori të vetën, p.sh. FZ dhe APT në të njëjtin lloj dhome.',
    el: 'Χρειάζεται μόνο αν ένα κανάλι πουλά αυτό το δωμάτιο με δική του κατηγορία, π.χ. FZ και APT στην ίδια κατηγορία δωματίων.',
    lt: 'Reikia tik tada, jei kanalas parduoda šį kambarį savo kategorijoje, pvz., FZ ir APT tame pačiame kambario tipe.',
    lv: 'Vajadzīgs tikai tad, ja kāds kanāls pārdod šo numuru ar savu kategoriju, piemēram, FZ un APT vienā numuru tipā.',
    et: 'Vajalik ainult siis, kui mõni kanal müüb seda tuba oma kategooria all, nt FZ ja APT samas toagrupis.' },
