  'master.qualityHint': {
    de: '0 bis 100, gewöhnlich 50. Beim Sortieren bekommen die besten Zimmer die Gäste, für die sie sich lohnen.',
    en: '0 to 100, usually 50. When sorting, the best rooms go to the guests they pay off for.',
    tr: '0 ile 100 arası, genelde 50. Sıralamada en iyi odalar en çok değer katan misafirlere verilir.',
    nl: '0 tot 100, meestal 50. Bij het sorteren krijgen de beste kamers de gasten voor wie ze het meest opleveren.',
    da: '0 til 100, normalt 50. Ved sortering får de bedste værelser de gæster, det betaler sig for.',
    sv: '0 till 100, normalt 50. Vid sortering får de bästa rummen de gäster där de lönar sig.',
    nb: '0 til 100, vanligvis 50. Ved sortering går de beste rommene til gjestene der de lønner seg.',
    pl: 'Od 0 do 100, zwykle 50. Przy sortowaniu najlepsze pokoje dostają goście, dla których to się opłaca.',
    cs: '0 až 100, obvykle 50. Při řazení dostanou nejlepší pokoje hosté, u nichž se to vyplatí.',
    fr: 'De 0 à 100, généralement 50. Au tri, les meilleures chambres vont aux clients pour qui elles sont rentables.',
    it: 'Da 0 a 100, di solito 50. Nell’ordinamento le camere migliori vanno agli ospiti per cui conviene.',
    es: 'De 0 a 100, normalmente 50. Al ordenar, las mejores habitaciones van a los huéspedes para los que más compensan.',
    ru: 'От 0 до 100, обычно 50. При распределении лучшие номера достаются гостям, для которых это выгоднее.',
    uk: 'Від 0 до 100, зазвичай 50. Під час сортування найкращі номери отримують ті гості, для яких це вигідно.',
    zh: '0 到 100，通常为 50。排房时，最好的客房会分给最值得的宾客。',
    ko: '0~100, 보통 50. 정렬 시 가장 좋은 객실이 가치가 있는 게스트에게 배정됩니다.',
    ar: 'من 0 إلى 100، عادةً 50. عند الفرز تذهب أفضل الغرف إلى النزلاء الذين تستحق لهم.',
    pt: '0 a 100, normalmente 50. Ao ordenar, os melhores quartos vão para os hóspedes para quem compensam.',
    fi: '0–100, yleensä 50. Lajittelussa parhaat huoneet saavat vieraat, joille ne kannattavat.',
    is: '0 til 100, venjulega 50. Við röðun fá bestu herbergin þá gesti sem þau borga sig fyrir.',
    sk: '0 až 100, obvykle 50. Pri triedení dostanú najlepšie izby hostia, pre ktorých sa oplatia.',
    sl: '0 do 100, običajno 50. Pri razvrščanju dobijo najboljše sobe gostje, pri katerih se to splača.',
    hu: '0-tól 100-ig, általában 50. Rendezéskor a legjobb szobák azokhoz a vendégekhez kerülnek, akiknél ez megéri.',
    ro: '0 până la 100, de obicei 50. La sortare, cele mai bune camere merg la oaspeții pentru care merită.',
    bg: 'От 0 до 100, обикновено 50. При сортиране най-добрите стаи получават гостите, за които си заслужава.',
    hr: '0 do 100, obično 50. Pri raspoređivanju najbolje sobe dobivaju gosti za koje se to isplati.',
    sr: 'Od 0 do 100, obično 50. Pri raspoređivanju najbolje sobe dobijaju gosti za koje se to isplati.',
    mk: '0 до 100, обично 50. При распоредување најдобрите соби ги добиваат гостите за кои тоа се исплати.',
    sq: '0 deri 100, zakonisht 50. Gjatë renditjes, dhomat më të mira u shkojnë mysafirëve për të cilët ia vlen.',
    el: '0 έως 100, συνήθως 50. Κατά την ταξινόμηση τα καλύτερα δωμάτια πηγαίνουν στους επισκέπτες για τους οποίους αξίζουν.',
    lt: 'Nuo 0 iki 100, paprastai 50. Rūšiuojant geriausi kambariai atitenka svečiams, kuriems jie labiausiai apsimoka.',
    lv: 'No 0 līdz 100, parasti 50. Kārtojot labākie numuri tiek tiem viesiem, kuriem tie atmaksājas.',
    et: '0 kuni 100, tavaliselt 50. Sorteerimisel saavad parimad toad need külalised, kelle puhul see end ära tasub.' },
