  'master.buildingHint': {
    de: 'Etwa Haupthaus oder Nebenhaus. Eine Gruppe wird möglichst in einem Gebäude untergebracht.',
    en: 'For example main or annex building. A group is kept in one building where possible.',
    tr: 'Örneğin ana bina veya ek bina. Grup mümkünse tek binada tutulur.',
    nl: 'Bijvoorbeeld hoofdgebouw of bijgebouw. Een groep wordt zo mogelijk in één gebouw ondergebracht.',
    da: 'F.eks. hovedbygning eller anneks. En gruppe placeres så vidt muligt i én bygning.',
    sv: 'T.ex. huvudbyggnad eller annex. En grupp placeras om möjligt i en byggnad.',
    nb: 'For eksempel hovedbygning eller annekst. En gruppe innkvarteres helst i én bygning.',
    pl: 'Np. budynek główny lub dependance. Grupa jest w miarę możliwości kwaterowana w jednym budynku.',
    cs: 'Např. hlavní budova nebo přístavba. Skupina se ubytuje pokud možno v jedné budově.',
    fr: 'Par exemple bâtiment principal ou annexe. Un groupe est logé si possible dans un seul bâtiment.',
    it: 'Ad esempio edificio principale o dépendance. Un gruppo viene sistemato possibilmente in un solo edificio.',
    es: 'P. ej. edificio principal o anexo. Un grupo se aloja, en lo posible, en un mismo edificio.',
    ru: 'Например, главный корпус или пристройка. Группу по возможности размещают в одном корпусе.',
    uk: 'Напр. головний корпус або флігель. Групу по змозі розміщують в одній будівлі.',
    zh: '例如主楼或副楼。团队会尽量安排在同一栋楼。',
    ko: '예: 본관 또는 별관. 단체는 가능한 한 한 건물에 배정됩니다.',
    ar: 'مثل المبنى الرئيسي أو الملحق. تُسكَّن المجموعة في مبنى واحد قدر الإمكان.',
    pt: 'Por exemplo, edifício principal ou anexo. Um grupo é alojado, sempre que possível, num só edifício.',
    fi: 'Esimerkiksi päärakennus tai sivurakennus. Ryhmä majoitetaan mahdollisuuksien mukaan samaan rakennukseen.',
    is: 'Til dæmis aðalhús eða viðbygging. Hópur er hafður í einni byggingu ef hægt er.',
    sk: 'Napríklad hlavná budova alebo vedľajšia budova. Skupina sa podľa možnosti ubytuje v jednej budove.',
    sl: 'Npr. glavna stavba ali depandansa. Skupina je po možnosti nameščena v eni stavbi.',
    hu: 'Például főépület vagy melléképület. Egy csoport lehetőleg egy épületben kerül elhelyezésre.',
    ro: 'De ex. clădirea principală sau anexa. Un grup este cazat pe cât posibil într-o singură clădire.',
    bg: 'Например основна сграда или пристройка. Групата се настанява по възможност в една сграда.',
    hr: 'Npr. glavna zgrada ili depandansa. Grupa se po mogućnosti smješta u jednu zgradu.',
    sr: 'Npr. glavna zgrada ili aneks. Grupa se po mogućnosti smešta u jednu zgradu.',
    mk: 'На пр. главна зграда или анекс. Групата по можност се сместува во една зграда.',
    sq: 'P.sh. ndërtesa kryesore ose aneksi. Një grup vendoset sipas mundësisë në një ndërtesë.',
    el: 'Π.χ. κεντρικό κτίριο ή παράρτημα. Μια ομάδα τοποθετείται κατά το δυνατόν σε ένα κτίριο.',
    lt: 'Pvz., pagrindinis pastatas arba priestatas. Grupė pagal galimybes apgyvendinama viename pastate.',
    lv: 'Piemēram, galvenā ēka vai piebūve. Grupu pēc iespējas izmitina vienā ēkā.',
    et: 'Nt peahoone või kõrvalhoone. Grupp majutatakse võimaluse korral ühte hoonesse.' },
