  'avsSettings.hint': {
    de: 'Beim Check-in entsteht je Aufenthalt eine Datei für AVS, die die Rezeption sofort einliest; dort entsteht die Gästekarte. Die Objektnummer vergibt die Kurverwaltung.',
    en: 'At check-in, one file per stay is created for AVS, which the front desk imports right away; the guest card is created there. The property number is assigned by the spa administration.',
    tr: 'Check-in sırasında her konaklama için AVS\'ye bir dosya oluşturulur ve resepsiyon bunu hemen içe aktarır; misafir kartı orada oluşur. Tesis numarasını kur idaresi verir.',
    nl: 'Bij het inchecken ontstaat per verblijf een bestand voor AVS, dat de receptie direct inleest; daar ontstaat de gastenkaart. Het objectnummer wordt door de kuurbeheerder toegekend.',
    da: 'Ved check-in oprettes der pr. ophold en fil til AVS, som receptionen straks indlæser; der oprettes gæstekortet. Objektnummeret tildeles af kurforvaltningen.',
    sv: 'Vid incheckning skapas en fil per vistelse för AVS, som receptionen läser in direkt; där skapas gästkortet. Objektnumret delas ut av kurortsförvaltningen.',
    nb: 'Ved innsjekking opprettes én fil per opphold for AVS, som resepsjonen leser inn med en gang; der opprettes gjestekortet. Objektnummeret tildeles av kurforvaltningen.',
    pl: 'Przy zameldowaniu dla każdego pobytu powstaje plik dla AVS, który recepcja od razu wczytuje; tam powstaje karta gościa. Numer obiektu nadaje zarząd uzdrowiska.',
    cs: 'Při check-inu vznikne pro každý pobyt soubor pro AVS, který recepce ihned načte; tam vznikne karta hosta. Číslo objektu přiděluje lázeňská správa.',
    fr: 'Au check-in, un fichier par séjour est créé pour AVS, que la réception importe aussitôt ; la carte d’hôte y est créée. Le numéro d’établissement est attribué par l’administration thermale.',
    it: 'Al check-in viene creato per ogni soggiorno un file per AVS, che la reception importa subito; lì viene creata la carta ospite. Il numero della struttura è assegnato dall’amministrazione termale.',
    es: 'En el check-in se genera por estancia un archivo para AVS, que la recepción importa de inmediato; allí se crea la tarjeta de huésped. El número de establecimiento lo asigna la administración del balneario.',
    ru: 'При заселении для каждого проживания создаётся файл для AVS, который стойка регистрации сразу загружает; там создаётся гостевая карта. Номер объекта выдаёт курортная администрация.',
    uk: 'Під час check-in для кожного проживання створюється файл для AVS, який рецепція одразу імпортує; там створюється картка гостя. Номер об’єкта надає курортна адміністрація.',
    zh: '办理入住时，每次入住会为 AVS 生成一个文件，前台立即导入；宾客卡在 AVS 中生成。物业编号由疗养地管理处分配。',
    ko: '체크인 시 숙박마다 AVS용 파일이 생성되며, 프런트가 이를 바로 불러옵니다. 게스트 카드는 AVS에서 발급됩니다. 시설 번호는 관광청(Kurverwaltung)이 부여합니다.',
    ar: 'عند تسجيل الوصول يُنشأ لكل إقامة ملف لـ AVS، يستورده الاستقبال فورًا؛ وهناك تُنشأ بطاقة النزيل. رقم المنشأة تمنحه إدارة المنتجع.',
    pt: 'No check-in é criado, por estadia, um ficheiro para o AVS, que a receção importa de imediato; é aí que é criado o cartão de hóspede. O número do estabelecimento é atribuído pela administração turística local.',
    fi: 'Sisäänkirjautumisessa jokaisesta oleskelusta syntyy AVS:lle tiedosto, jonka vastaanotto lukee heti sisään; siellä syntyy vieraskortti. Kohdenumeron antaa kylpyläkunnan hallinto.',
    is: 'Við innritun verður til ein skrá á hverja dvöl fyrir AVS, sem móttakan les strax inn; þar verður gestakortið til. Gististaðarnúmerið úthlutar heilsulindarstjórnin.',
    sk: 'Pri check-ine vznikne za každý pobyt súbor pre AVS, ktorý recepcia hneď načíta; tam vznikne karta hosťa. Číslo objektu prideľuje kúpeľná správa.',
    sl: 'Ob prijavi gosta nastane za vsako bivanje datoteka za AVS, ki jo recepcija takoj uvozi; tam nastane kartica gosta. Številko objekta dodeli turistična uprava.',
    hu: 'Check-inkor tartózkodásonként egy fájl készül az AVS számára, amelyet a recepció azonnal beolvas; ott jön létre a vendégkártya. Az objektumszámot a fürdőigazgatóság adja ki.',
    ro: 'La check-in se creează pentru fiecare sejur un fișier pentru AVS, pe care recepția îl importă imediat; acolo se creează cardul de oaspete. Numărul unității îl atribuie administrația stațiunii.',
    bg: 'При настаняване за всеки престой се създава файл за AVS, който рецепцията веднага зарежда; там се създава картата на госта. Номерът на обекта се дава от курортната администрация.',
    hr: 'Pri prijavi gosta za svaki boravak nastaje datoteka za AVS koju recepcija odmah učitava; ondje nastaje kartica gosta. Broj objekta dodjeljuje turistička uprava.',
    sr: 'Pri check-inu za svaki boravak nastaje datoteka za AVS, koju recepcija odmah učitava; tamo nastaje kartica gosta. Broj objekta dodeljuje turistička uprava.',
    mk: 'При check-in за секој престој се создава датотека за AVS, која рецепцијата веднаш ја вчитува; таму се создава гостинската картичка. Бројот на објектот го доделува туристичката управа.',
    sq: 'Gjatë check-in krijohet për çdo qëndrim një skedar për AVS, të cilin recepsioni e lexon menjëherë; aty krijohet karta e mysafirit. Numrin e objektit e cakton administrata e kurortit.',
    el: 'Κατά το check-in δημιουργείται ανά διαμονή ένα αρχείο για το AVS, το οποίο η ρεσεψιόν εισάγει αμέσως· εκεί δημιουργείται η κάρτα επισκέπτη. Τον αριθμό καταλύματος τον δίνει η διοίκηση της λουτρόπολης.',
    lt: 'Registruojant atvykimą kiekvienai viešnagei sukuriamas failas AVS sistemai, kurį registratūra iš karto įkelia; ten sukuriama svečio kortelė. Objekto numerį suteikia kurorto administracija.',
    lv: 'Reģistrējot viesi, katrai uzturēšanās reizei tiek izveidots fails AVS, ko reģistratūra uzreiz ielasa; tur tiek izveidota viesa karte. Objekta numuru piešķir kūrorta pārvalde.',
    et: 'Sisseregistreerimisel luuakse iga viibimise kohta AVS-i jaoks fail, mille vastuvõtt kohe sisse loeb; seal luuakse külaliskaart. Objekti numbri annab kuurordi haldus.' },
