  'avsSettings.moreHint': {
    de: 'Sagen AVS nur, aus welchem Programm die Datei kommt. Vorbelegt mit „StayGrid“; ändern muss sie niemand.',
    en: 'Only tell AVS which program the file comes from. Preset to “StayGrid”; nobody needs to change them.',
    tr: 'Yalnızca dosyanın hangi programdan geldiğini AVS\'ye bildirir. “StayGrid” olarak önceden ayarlıdır; değiştirmek gerekmez.',
    nl: 'Vertellen AVS alleen uit welk programma het bestand komt. Vooraf ingevuld met “StayGrid”; niemand hoeft ze te wijzigen.',
    da: 'Fortæller kun AVS, hvilket program filen kommer fra. Forudfyldt med „StayGrid“; ingen behøver at ændre dem.',
    sv: 'Talar bara om för AVS vilket program filen kommer från. Förinställt på ”StayGrid”; ingen behöver ändra dem.',
    nb: 'Forteller bare AVS hvilket program filen kommer fra. Forhåndsutfylt med «StayGrid»; ingen trenger å endre dem.',
    pl: 'Informują AVS tylko o tym, z jakiego programu pochodzi plik. Wstępnie ustawione na „StayGrid”; nikt nie musi ich zmieniać.',
    cs: 'Sdělují AVS jen to, z jakého programu soubor pochází. Předvyplněno „StayGrid“; nikdo je nemusí měnit.',
    fr: 'Indiquent seulement à AVS de quel programme vient le fichier. Préréglés sur « StayGrid » ; personne n’a besoin de les modifier.',
    it: 'Indicano ad AVS solo da quale programma proviene il file. Preimpostati su «StayGrid»; nessuno deve modificarli.',
    es: 'Solo indican a AVS de qué programa procede el archivo. Preestablecido como «StayGrid»; nadie necesita cambiarlos.',
    ru: 'Лишь сообщают AVS, из какой программы пришёл файл. Заполнено значением «StayGrid»; менять никому не нужно.',
    uk: 'Лише повідомляють AVS, з якої програми надійшов файл. Типове значення «StayGrid»; змінювати нікому не потрібно.',
    zh: '仅告诉 AVS 文件来自哪个程序。预设为“StayGrid”；无需更改。',
    ko: 'AVS에 파일이 어떤 프로그램에서 왔는지만 알려줍니다. 기본값은 „StayGrid“이며 변경할 필요가 없습니다.',
    ar: 'تخبر AVS فقط بالبرنامج الذي جاء منه الملف. قيمتها المسبقة «StayGrid»؛ ولا حاجة لأحد لتغييرها.',
    pt: 'Só indicam ao AVS de que programa vem o ficheiro. Predefinido com «StayGrid»; ninguém precisa de os alterar.',
    fi: 'Kertovat AVS:lle vain, mistä ohjelmasta tiedosto tulee. Oletuksena ”StayGrid”; kenenkään ei tarvitse muuttaa niitä.',
    is: 'Segja AVS aðeins úr hvaða forriti skráin kemur. Forstillt á „StayGrid“; enginn þarf að breyta þeim.',
    sk: 'Hovoria AVS len to, z ktorého programu súbor pochádza. Predvyplnené ako „StayGrid“; nikto ich nemusí meniť.',
    sl: 'Za AVS povedo le, iz katerega programa prihaja datoteka. Prednastavljeno na „StayGrid“; nihče jih ne rabi spreminjati.',
    hu: 'Csak azt mondják meg az AVS-nek, melyik programból származik a fájl. Előre kitöltve „StayGrid” értékkel; senkinek sem kell módosítania.',
    ro: 'Îi spun AVS doar din ce program provine fișierul. Precompletat cu „StayGrid”; nimeni nu trebuie să le modifice.',
    bg: 'Само казват на AVS от коя програма идва файлът. Предварително попълнено със „StayGrid“; никой не трябва да ги променя.',
    hr: 'Samo govore AVS-u iz kojeg programa dolazi datoteka. Unaprijed postavljeno na „StayGrid“; nitko ih ne mora mijenjati.',
    sr: 'Samo govore AVS-u iz kog programa dolazi datoteka. Unapred popunjeno sa „StayGrid“; niko ne mora da ih menja.',
    mk: 'Му кажуваат на AVS само од која програма доаѓа датотеката. Претходно поставено на „StayGrid“; никој не мора да ги менува.',
    sq: 'I tregojnë AVS-së vetëm nga cili program vjen skedari. Të paracaktuara me „StayGrid“; askush nuk ka nevojë t’i ndryshojë.',
    el: 'Λένε στο AVS μόνο από ποιο πρόγραμμα προέρχεται το αρχείο. Προσυμπληρωμένο με «StayGrid»· δεν χρειάζεται να αλλάξει.',
    lt: 'Tik nurodo AVS, iš kokios programos atėjo failas. Iš anksto nustatyta „StayGrid“; keisti nereikia.',
    lv: 'Tikai paziņo AVS, no kuras programmas nāk fails. Iepriekš aizpildīts ar “StayGrid”; nevienam tie nav jāmaina.',
    et: 'Ütlevad AVS-ile ainult, millisest programmist fail tuleb. Eeltäidetud väärtusega „StayGrid“; keegi ei pea neid muutma.' },
