    zh: '减免宾客的类别在“疗养税减免”下的各项原因中设置。',
    ko: '면제 게스트의 카테고리는 „Kurtaxe(관광세) 면제“의 각 사유에서 설정합니다.',
    ar: 'الفئة الخاصة بالنزلاء المعفيين تُحدد عند كل سبب ضمن «الإعفاء من رسوم الإقامة السياحية».',
    pt: 'A categoria para hóspedes isentos está em cada motivo, em «Isenção de taxa turística».',
