    sq: 'Ende asnjë arsye. Pa arsye, formulari i regjistrimit nuk pyet për përjashtim.',
    el: 'Δεν υπάρχουν ακόμη λόγοι. Χωρίς λόγους το έντυπο δήλωσης διαμονής δεν ρωτά για απαλλαγή.',
